// DayRevenue is what an organization took on one day in one currency.
type DayRevenue struct {
	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Group is how a report groups days into buckets.
type Group string

// Groups.
const (
	GroupDay   Group = "day"
	GroupWeek  Group = "week" // starts on Monday
	GroupMonth Group = "month"
)

// Bucket is what an organization took in one day, week or month. Amounts has an entry per currency with payments.
type Bucket struct {
	Start    string                   `json:"start"` // YYYY-MM-DD, the first day of the bucket
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                      `json:"payments"`
}

// Report is the revenue of an organization, grouped in its own time zone.
type Report struct {
	TimeZone string   `json:"time_zone"`
	Group    Group    `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	_, _, first, last, err := window(st, orgID, from, to)
	if err != nil {
		return nil, err
	}
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, d := range succeededPayments(st, orgID, nil, first, last) {
		k := key{d.day.Format(time.DateOnly), d.p.Currency}
		r, ok := sums[k]
		if !ok {
			r = &DayRevenue{Date: k.day, Currency: k.cur}
			sums[k] = r
		}
		r.Amount += d.p.Amount
		r.Payments++
	}
	out := make([]DayRevenue, 0, len(sums))
	for _, r := range sums {
		out = append(out, *r)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		return out[i].Currency < out[j].Currency
	})
	return out, nil
}

// RevenueReport adds up the organization's succeeded payments per day, week or month (group; the empty group is day) from
// the day from to the day to (YYYY-MM-DD, both included). Days are days in the organization's time zone, so a payment
// belongs to the day it was made there. Every bucket from the one holding from to the one holding to is in the report, in
// order, also those without payments.
func RevenueReport(st *store.Store, orgID, from, to string, group Group) (Report, error) {
	org, loc, first, last, err := window(st, orgID, from, to)
	if err != nil {
		return Report{}, err
	}
	if group == "" {
		group = GroupDay
	}
	if group != GroupDay && group != GroupWeek && group != GroupMonth {
		return Report{}, fmt.Errorf("%w: %q", ErrInvalidGroup, group)
	}
	r := Report{TimeZone: org.TimeZone, Group: group, Buckets: []Bucket{}}
	index := map[string]int{}
	for b, end := bucketStart(first, group), bucketStart(last, group); !b.After(end); b = nextBucket(b, group) {
		index[b.Format(time.DateOnly)] = len(r.Buckets)
		r.Buckets = append(r.Buckets, Bucket{Start: b.Format(time.DateOnly), Amounts: map[money.Currency]int64{}})
	}
	for _, d := range succeededPayments(st, orgID, loc, first, last) {
		b := &r.Buckets[index[bucketStart(d.day, group).Format(time.DateOnly)]]
		b.Amounts[d.p.Currency] += d.p.Amount
		b.Payments++
	}
	return r, nil
}

// window checks the range and returns the organization's time zone with the first and last day of the range, as UTC
// dates (calendar days, so they have no time zone of their own).
func window(st *store.Store, orgID, from, to string) (store.Org, *time.Location, time.Time, time.Time, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return store.Org{}, nil, time.Time{}, time.Time{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return store.Org{}, nil, time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return store.Org{}, nil, time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return store.Org{}, nil, time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	org, ok := st.Org(orgID)
	if !ok {
		return store.Org{}, nil, time.Time{}, time.Time{}, store.ErrNotFound
	}
	loc, err := time.LoadLocation(org.TimeZone)
	if err != nil {
		return store.Org{}, nil, time.Time{}, time.Time{}, fmt.Errorf("organization time zone %q: %w", org.TimeZone, err)
	}
	return org, loc, start, last, nil
}

// datedPayment is a succeeded payment and the day it was made on, in the time zone it was dated in.
type datedPayment struct {
	day time.Time // a UTC date
	p   store.Payment
}

// succeededPayments returns the organization's succeeded payments made on days from first to last (UTC dates) in loc. With
// a nil loc the days are UTC days.
func succeededPayments(st *store.Store, orgID string, loc *time.Location, first, last time.Time) []datedPayment {
	if loc == nil {
		loc = time.UTC
	}
	var out []datedPayment
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded {
			continue
		}
		local := p.CreatedAt.In(loc)
		day := time.Date(local.Year(), local.Month(), local.Day(), 0, 0, 0, 0, time.UTC)
		if day.Before(first) || day.After(last) {
			continue
		}
		out = append(out, datedPayment{day: day, p: p})
	}
	return out
}

// bucketStart is the first day of the group's bucket that holds day d (a UTC date).
func bucketStart(d time.Time, group Group) time.Time {
	switch group {
	case GroupWeek:
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7)) // back to Monday
	case GroupMonth:
		return time.Date(d.Year(), d.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return d
}

// nextBucket is the first day of the bucket after the one starting on b.
func nextBucket(b time.Time, group Group) time.Time {
	switch group {
	case GroupWeek:
		return b.AddDate(0, 0, 7)
	case GroupMonth:
		return b.AddDate(0, 1, 0)
	}
	return b.AddDate(0, 0, 1)
}
